def step(n):
    total = 0
    for d in str(n):
        total += int(d) ** 2
    return total

def is_happy(n):
    slow, fast = n, step(n)
    while fast != 1 and slow != fast:
        slow = step(slow)
        fast = step(step(fast))
    return fast == 1

print(is_happy(n))

